<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api'
import { categories, categoryById, initials, percentage } from '../utils'
import { useUI } from '../stores/ui'
import Modal from '../components/Modal.vue'
import ProfileForm from '../components/ProfileForm.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import EmptyState from '../components/EmptyState.vue'
import TaskSelection from '../components/TaskSelection.vue'
const route = useRoute(), router = useRouter(), ui = useUI(), id = Number(route.params.id)
const profile = ref(null), loading = ref(true), error = ref(''), category = ref('stress'), editing = ref(false), confirmation = ref(null), selecting = ref(null)
const attaching = ref(false), library = ref({ folders: [], lists: [] }), attachLoading = ref(false), busy = ref(false), attachSearch = ref(''), attachIds = ref(new Set())
const lists = computed(() => profile.value?.lists.filter(l => l.category === category.value) || [])
const total = computed(() => lists.value.reduce((a, l) => a + l.total, 0)), correct = computed(() => lists.value.reduce((a, l) => a + l.correct, 0))
const attachable = computed(() => {
  const folderIds = library.value.folders.filter(f => f.category === category.value).map(f => f.id)
  return library.value.lists.filter(l => folderIds.includes(l.folder_id) && !profile.value?.lists.some(p => p.id === l.id) && l.name.toLowerCase().includes(attachSearch.value.toLowerCase()))
})
async function load() { error.value = ''; try { profile.value = await api(`/profiles/${id}`) } catch (e) { error.value = e.message } finally { loading.value = false } }
onMounted(load)
async function openAttach() {
  attaching.value = true; attachLoading.value = true; attachIds.value = new Set(); attachSearch.value = ''; error.value = ''
  try { library.value = await api('/library') } catch (e) { ui.notify(e.message, 'error'); attaching.value = false } finally { attachLoading.value = false }
}
function toggleAttach(itemId) { const ids = new Set(attachIds.value); ids.has(itemId) ? ids.delete(itemId) : ids.add(itemId); attachIds.value = ids }
async function attach() {
  busy.value = true
  try {
    for (const listId of attachIds.value) await api(`/profiles/${id}/lists`, { method: 'POST', body: { list_id: listId } })
    attaching.value = false; await load(); ui.notify('Списки прикреплены к профилю')
  } catch (e) { ui.notify(e.message, 'error'); await load() } finally { busy.value = false }
}
async function confirmed(done) {
  try {
    const c = confirmation.value
    if (c.type === 'profile') { await api(`/profiles/${id}`, { method: 'DELETE' }); router.push('/profiles'); ui.notify('Профиль удалён') }
    else if (c.type === 'category') {
      for (const list of lists.value) await api(`/profiles/${id}/lists/${list.id}/progress`, { method: 'DELETE' })
      await load(); ui.notify('Прогресс раздела сброшен')
    } else {
      await api(`/profiles/${id}/lists/${c.list.id}${c.type === 'reset' ? '/progress' : ''}`, { method: 'DELETE' })
      await load(); ui.notify(c.type === 'reset' ? 'Прогресс сброшен' : 'Список откреплён')
    }
    confirmation.value = null
  } catch (e) { ui.notify(e.message, 'error') } finally { done() }
}
</script>
<template>
  <div v-if="loading" class="loading"><Icon name="LoaderCircle" class="spin" />Открываем профиль…</div><div v-else-if="!profile" class="error-box">{{ error }} <RouterLink to="/profiles" class="underline">Вернуться к профилям</RouterLink></div>
  <section v-else><div class="breadcrumbs"><RouterLink to="/profiles">Учебные профили</RouterLink><Icon name="ChevronRight" :size="13" /><span>{{ profile.name }}</span></div><div class="page-heading profile-heading"><div class="flex items-center gap-4"><div class="profile-big-avatar"><Icon v-if="profile.kind === 'group'" name="Users" :size="27" /><span v-else>{{ initials(profile.name) }}</span></div><div><span class="badge neutral mb-2">{{ profile.kind === 'group' ? 'Учебная группа' : 'Ученик' }}</span><h1>{{ profile.name }}</h1><p v-if="profile.note" class="profile-description">{{ profile.note }}</p></div></div><div class="flex gap-2"><button class="btn secondary" @click="editing = true"><Icon name="Settings2" :size="16" />Настройки</button><button class="icon-btn red" aria-label="Удалить профиль" @click="confirmation = { type: 'profile', title: 'Удалить учебный профиль?', message: `«${profile.name}» и весь прогресс будут безвозвратно удалены. Списки в базе заданий сохранятся.`, action: 'Удалить профиль' }"><Icon name="Trash2" :size="17" /></button></div></div>
    <div class="profile-category-tabs"><button v-for="cat in categories" :key="cat.id" :class="{ active: category === cat.id }" @click="category = cat.id"><Icon :name="cat.icon" :size="17" /><span>{{ cat.name }}</span><span class="tab-count">{{ profile.lists.filter(l => l.category === cat.id).length }}</span></button></div>
    <div class="section-progress card"><div class="section-progress-icon"><Icon name="Target" :size="24" /></div><div class="section-progress-main"><div class="section-progress-title"><h3>Общий прогресс раздела</h3><span>{{ correct }} <span>/ {{ total }}</span> <strong>{{ percentage(correct, total) }}%</strong></span></div><div class="progress-track"><div :style="{ width: percentage(correct, total) + '%' }"></div></div></div><button class="btn ghost sm" :disabled="!total" @click="confirmation = { type: 'category', title: 'Сбросить прогресс раздела?', message: 'Результаты всех списков текущего раздела будут сброшены. Сами задания останутся на месте.', action: 'Сбросить прогресс' }"><Icon name="RotateCcw" :size="14" /><span>Сбросить прогресс</span></button></div>
    <div class="section-heading"><h2>Списки для занятий<span class="count-badge">{{ lists.length }}</span></h2><button class="btn primary" @click="openAttach"><Icon name="Plus" :size="16" />Прикрепить список</button></div><div v-if="error" class="error-box mb-4">{{ error }}</div>
    <div v-if="lists.length" class="attached-lists"><article v-for="list in lists" :key="list.id" class="attached-card card"><div class="attached-main"><div class="file-icon"><Icon name="FileText" :size="22" /></div><button class="attached-title" @click="selecting = list"><h3>{{ list.name }}</h3><p>{{ list.folder }}<span class="mx-2">·</span>{{ list.total }} заданий</p></button><div class="attached-actions"><button class="icon-btn" title="Сбросить прогресс списка" aria-label="Сбросить прогресс списка" @click="confirmation = { type: 'reset', list, title: 'Сбросить прогресс списка?', message: `Все результаты по списку «${list.name}» станут новыми.`, action: 'Сбросить прогресс' }"><Icon name="RotateCcw" :size="15" /></button><button class="icon-btn red" title="Открепить список" aria-label="Открепить список" @click="confirmation = { type: 'detach', list, title: 'Открепить список?', message: `Список «${list.name}» исчезнет из этого профиля, но останется в базе заданий. Прогресс сохранится при повторном прикреплении.`, action: 'Открепить' }"><Icon name="X" :size="16" /></button></div></div><div class="attached-progress"><div class="attached-progress-caption"><span>Освоено <strong>{{ list.correct }} / {{ list.total }}</strong></span><span>{{ percentage(list.correct, list.total) }}%</span></div><div class="progress-track"><div :style="{ width: percentage(list.correct, list.total) + '%' }"></div></div></div><div class="attached-bottom"><div class="flex gap-2 flex-wrap"><span class="badge green"><Icon name="Check" :size="11" />{{ list.correct }} изучено</span><span v-if="list.mistakes" class="badge rose">{{ list.mistakes }} с ошибками</span><span v-if="list.review" class="badge amber">{{ list.review }} проверить</span></div><button class="btn soft sm" @click="selecting = list"><Icon name="Play" :size="13" />Тренироваться<Icon name="ArrowRight" :size="13" /></button></div></article></div><EmptyState v-else icon="BookOpen" title="Добавим немного практики?" :text="`Прикрепите списки из раздела «${categoryById(category).name}», чтобы начать тренировку и отслеживать прогресс.`" action="Выбрать списки из базы" @action="openAttach" />
  </section>
  <ProfileForm v-if="editing" :profile="profile" @close="editing = false" @saved="editing = false; load()" />
  <Modal v-if="attaching" title="Выберите списки из базы" :subtitle="categoryById(category).name" @close="!busy && (attaching = false)"><div class="modal-body"><div class="search-field attach-search"><Icon name="Search" :size="15" /><input v-model="attachSearch" placeholder="Поиск по названию…" aria-label="Поиск списков" /></div><div v-if="attachLoading" class="loading"><Icon name="LoaderCircle" class="spin" /></div><div v-else-if="attachable.length" class="attach-options"><label v-for="list in attachable" :key="list.id"><input type="checkbox" :checked="attachIds.has(list.id)" :disabled="busy" @change="toggleAttach(list.id)" /><div><strong>{{ list.name }}</strong><p>{{ library.folders.find(f => f.id === list.folder_id)?.name }} · {{ list.count }} заданий</p></div></label></div><EmptyState v-else icon="FileText" title="Пока нет доступных списков" text="Создайте список в базе заданий или выберите другой раздел. Уже прикреплённые списки здесь не показываются." /><RouterLink to="/library" class="text-xs text-sky-600 inline-flex gap-2 items-center mt-4" @click="attaching = false">Перейти в базу заданий<Icon name="ArrowUpRight" :size="13" /></RouterLink></div><footer class="modal-footer"><button class="btn secondary" :disabled="busy" @click="attaching = false">Отмена</button><button class="btn primary" :disabled="busy || !attachIds.size" @click="attach"><Icon :name="busy ? 'LoaderCircle' : 'Plus'" :class="{ spin: busy }" :size="16" />Прикрепить · {{ attachIds.size }}</button></footer></Modal>
  <ConfirmDialog v-if="confirmation" :title="confirmation.title" :message="confirmation.message" :action="confirmation.action" @close="confirmation = null" @confirm="confirmed" />
  <TaskSelection v-if="selecting" :profile-id="id" :list="selecting" @close="selecting = null" />
</template>
<style scoped>
