items:center;gap:12px}.attached-title{text-align:left;border:0;background:none;flex:1;min-width:0}.attached-title h3{font-size:13px;overflow-wrap:anywhere;line-height:1.6}.attached-title p{font-size:9px;color:#9eafc0;margin-top:5px}.attached-actions{display:flex;gap:0;align-self:flex-start}.attached-actions .icon-btn{width:25px;height:25px}.attached-progress{margin:25px 0 22px}.attached-progress-caption{display:flex;justify-content:space-between;font-size:9px;color:#99afbd;margin-bottom:9px}.attached-progress-caption strong{font-weight:400;color:#8eb3a4;margin-left:5px}.attached-bottom{border-top:1px solid #edf2f7;padding-top:16px;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.attached-bottom .btn{font-size:10px;padding-inline:10px}.attach-search input{width:100%}.attach-options{display:grid;margin-top:19px;max-height:43vh;overflow:auto}.attach-options label{display:flex;gap:12px;align-items:center;padding:14px 0;border-bottom:1px solid #edf2f7;cursor:pointer}.attach-options input{accent-color:#0284c7;width:16px;height:16px;flex-shrink:0}.attach-options strong{font-size:12px;font-weight:500}.attach-options p{font-size:10px;color:#9aafc1;margin-top:5px}@media(max-width:1150px){.attached-lists{grid-template-columns:1fr}.section-progress>.btn span{display:none}}@media(max-width:760px){.profile-heading h1{font-size:25px}.profile-big-avatar{width:49px;height:49px;border-radius:15px;font-size:17px}.profile-category-tabs{gap:10px;justify-content:space-between}.profile-category-tabs>button{font-size:10px;gap:5px;align-items:flex-start}.profile-category-tabs>button>svg{width:14px;flex-shrink:0}.tab-count{display:none}.profile-category-tabs>button>span{max-width:110px;text-align:left}.section-progress{padding:16px;gap:11px}.section-progress-icon{width:36px;height:36px;border-radius:11px}.section-progress-icon svg{width:20px}.section-progress-title{flex-wrap:wrap;gap:7px}.section-progress-title h3{font-size:11px}.section-progress-main p{font-size:8px;line-height:1.7}.section-progress>.btn{margin-left:0;padding:6px}.section-progress-title strong{margin-left:5px}.section-heading .btn{font-size:10px;padding:9px 11px}.attached-card{padding:17px}}
</style>
